package br.com.lealinfo.vidraceiro;
import android.content.Context;import android.graphics.*;import android.view.*;import java.util.*;
/** Orthographic projection adapted from GlassBox3DView.cs; no manufacturing assumptions. */
final class ProjectDrawing extends View {
 double widthMm,heightMm,depthMm;boolean threeD=true,dimensions=true;float yaw=-25,pitch=18,zoom=1,lastX,lastY;int panels=1;final Paint paint=new Paint(3);final ScaleGestureDetector pinch;
 ProjectDrawing(Context c,double w,double h,double d,int count){super(c);widthMm=w;heightMm=h;depthMm=d;panels=count;setContentDescription("Representação do projeto em 2D e 3D");pinch=new ScaleGestureDetector(c,new ScaleGestureDetector.SimpleOnScaleGestureListener(){@Override public boolean onScale(ScaleGestureDetector s){zoom=Math.max(.55f,Math.min(2.5f,zoom*s.getScaleFactor()));invalidate();return true;}});}
 void reset(){yaw=-25;pitch=18;zoom=1;invalidate();}
 @Override protected void onDraw(Canvas c){super.onDraw(c);c.drawColor(Color.rgb(9,22,39));if(widthMm<=0||heightMm<=0)return;double max=Math.max(widthMm,Math.max(heightMm,depthMm)),w=widthMm/max*.5,h=heightMm/max*.5,d=depthMm/max*.5;
 // A missing depth is a plane, never an invented thickness or fabricated box.
 double[][] vertices={{-w,-h,-d},{w,-h,-d},{w,h,-d},{-w,h,-d},{-w,-h,d},{w,-h,d},{w,h,d},{-w,h,d}};float[][] projected=new float[8][3];double cy=Math.cos(Math.toRadians(threeD?yaw:0)),sy=Math.sin(Math.toRadians(threeD?yaw:0)),cp=Math.cos(Math.toRadians(threeD?pitch:0)),sp=Math.sin(Math.toRadians(threeD?pitch:0));double radius=Math.sqrt(w*w+h*h+d*d),scale=Math.min(getWidth(),getHeight()-70)*.36/Math.max(radius,.001)*zoom;
 for(int i=0;i<8;i++){double[] v=vertices[i];double x=v[0]*cy+v[2]*sy,z=-v[0]*sy+v[2]*cy;projected[i]=new float[]{(float)(getWidth()*.5+x*scale),(float)(getHeight()*.52-(v[1]*cp-z*sp)*scale),(float)(v[1]*sp+z*cp)};}
 int[][] faces={{0,1,2,3},{4,5,6,7},{0,1,5,4},{3,2,6,7},{0,3,7,4},{1,2,6,5}};Integer[] order={0,1,2,3,4,5};Arrays.sort(order,(a,b)->Float.compare(depth(projected,faces[a]),depth(projected,faces[b])));
 for(int f:order){if(depthMm==0&&f>0)continue;Path path=new Path();for(int i=0;i<4;i++){float[] p=projected[faces[f][i]];if(i==0)path.moveTo(p[0],p[1]);else path.lineTo(p[0],p[1]);}path.close();paint.setStyle(Paint.Style.FILL);paint.setColor(Color.argb(180,25+f*3,76+f*6,102+f*5));c.drawPath(path,paint);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(2);paint.setColor(Color.rgb(115,224,251));c.drawPath(path,paint);
 if(f==0||f==1)for(int i=1;i<panels;i++){float t=i/(float)panels;float[] a=projected[faces[f][0]],b=projected[faces[f][1]],e=projected[faces[f][3]],g=projected[faces[f][2]];c.drawLine(a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t,e[0]+(g[0]-e[0])*t,e[1]+(g[1]-e[1])*t,paint);}}
 paint.setStyle(Paint.Style.FILL);paint.setColor(Color.rgb(210,235,250));paint.setTextSize(14*getResources().getDisplayMetrics().scaledDensity);if(dimensions){c.drawText(fmt(widthMm)+" × "+fmt(heightMm)+" mm",16,28,paint);if(depthMm>0)c.drawText("Profundidade: "+fmt(depthMm)+" mm",16,52,paint);} }
 private String fmt(double d){return java.math.BigDecimal.valueOf(d).stripTrailingZeros().toPlainString().replace('.',',');}private float depth(float[][] p,int[] f){float d=0;for(int i:f)d+=p[i][2];return d;}
 @Override public boolean onTouchEvent(android.view.MotionEvent e){pinch.onTouchEvent(e);if(e.getActionMasked()==MotionEvent.ACTION_DOWN){lastX=e.getX();lastY=e.getY();getParent().requestDisallowInterceptTouchEvent(true);return true;}if(e.getActionMasked()==MotionEvent.ACTION_MOVE&&!pinch.isInProgress()&&e.getPointerCount()==1){yaw=(yaw+(e.getX()-lastX)*.5f)%360;pitch=Math.max(-75,Math.min(75,pitch-(e.getY()-lastY)*.5f));lastX=e.getX();lastY=e.getY();invalidate();return true;}if(e.getActionMasked()==MotionEvent.ACTION_UP||e.getActionMasked()==MotionEvent.ACTION_CANCEL){getParent().requestDisallowInterceptTouchEvent(false);performClick();}return true;}
 @Override public boolean performClick(){super.performClick();return true;}
}
